from pathlib import Path
import base64,re,json
r=Path(__file__).resolve().parents[1]
reference=r/'data/vehicles/references/M1A1_USMC_planform.png'
png=base64.b64encode(reference.read_bytes()).decode()
sx=7.9248/760;sy=3.6576/356
view='-4.5 -2.4 11 4.8'
